// Prepara la petición a la API de Google Gemini (capa gratuita)
const body = $input.first().json.body || $input.first().json;
const dataUrl = body.imagen || '';
const nivel = body.nivel === 'profesional' ? 'profesional' : 'sencillo';

const match = dataUrl.match(/^data:(image\/(?:jpeg|png|webp));base64,(.+)$/s);
if (!match) {
  throw new Error('Imagen no valida: se esperaba un dataURL base64 (jpeg/png/webp)');
}
const mimeType = match[1];
const base64 = match[2];

const sistemaBase = `Eres el asistente de valoracion visual de una clinica dental. Analizas fotografias de bocas/dientes enviadas por pacientes y das una PRIMERA VALORACION ORIENTATIVA, nunca un diagnostico.\n\nReglas obligatorias:\n- Si la imagen NO muestra una boca/dientes o la calidad impide valorarla, dilo y pide una foto mejor (buena luz, boca abierta, enfocada). No inventes hallazgos.\n- Describe solo lo visible: higiene/placa/sarro aparente, estado aparente de encias, alineacion, desgastes, manchas, posibles lesiones visibles. Usa lenguaje de probabilidad ('se aprecia', 'compatible con', 'podria'), nunca afirmaciones diagnosticas.\n- No prescribas medicamentos ni tratamientos concretos.\n- Indica una orientacion de urgencia: sin signos de alarma / conviene revision / conviene revision pronto.\n- Cierra siempre recomendando confirmacion con un odontologo (primera consulta gratuita en la clinica).\n- Responde en espanol, en el formato: **Lo que se aprecia en la foto:** (lista), **Es urgente?**, **Siguiente paso:**. Maximo 200 palabras.`;

const nivelInstr = nivel === 'profesional'
  ? 'NIVEL: PROFESIONAL. Usa terminologia clinica odontologica (nomenclatura FDI si identificas piezas, gingivitis/periodontitis, tartrectomia, lesiones cariosas, etc.), como un informe entre colegas.'
  : 'NIVEL: SENCILLO. Explica como a un paciente sin conocimientos, sin tecnicismos, con tono cercano y tranquilizador.';

return [{
  json: {
    payload: {
      systemInstruction: { parts: [{ text: sistemaBase + '\n\n' + nivelInstr }] },
      contents: [{
        role: 'user',
        parts: [
          { inline_data: { mime_type: mimeType, data: base64 } },
          { text: 'Valora esta fotografia dental segun tus instrucciones.' }
        ]
      }],
      generationConfig: { maxOutputTokens: 1024, temperature: 0.2 }
    }
  }
}];

// Extrae el texto de la respuesta de Gemini
const r = $input.first().json;
const cand = (r.candidates || [])[0];
if (!cand) {
  return [{ json: { resultado: '**No se ha podido analizar esta imagen.** Prueba con otra fotografia de tus dientes con buena luz.' } }];
}
if (cand.finishReason && cand.finishReason !== 'STOP' && cand.finishReason !== 'MAX_TOKENS') {
  return [{ json: { resultado: '**No se ha podido analizar esta imagen.** Envia una fotografia clara de tus dientes.' } }];
}
const texto = (cand.content?.parts || []).map(p => p.text).filter(Boolean).join('\n');
return [{ json: { resultado: texto || 'No se recibio respuesta del analisis.' } }];
